//! Bake the credits into the binary, from an app's `build.rs` (in its `fn main`):
//!
//! ```no_run
//! let manifest = std::path::PathBuf::from(std::env::var_os("CARGO_MANIFEST_DIR").unwrap_or_default());
//! craft_credits::build::write_credits(&manifest.join("../../contributors"));
//! ```
//!
//! and in the app: `include!(concat!(env!("OUT_DIR"), "/credits.rs"));`, which defines
//! `TOTAL_COMMITS: u64`, `CONTRIBUTORS: &[craft_credits::Contributor]` and
//! `MODELS: &[craft_credits::Model]`.
//!
//! - `contributors.json`: commit stats per GitHub username, generated by craftrules
//!   `scripts/contributors.py`, which also marks whose people.toml entry it verified.
//! - `people.toml`: the names people chose for themselves. A name is used only when the JSON says
//!   the entry was verified (`people_entry`).
//!
//! A missing or malformed file gives empty tables (or no names) and a cargo warning, never a failed
//! build.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// One contributor as read from the files, before it is written as Rust.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Person {
    pub login: String,
    pub display_name: Option<String>,
    pub real_name: Option<String>,
    pub prs: u64,
    pub commits: u64,
    pub lines_added: u64,
    pub lines_deleted: u64,
    pub binary_added: u64,
    pub binary_deleted: u64,
    pub first_commit: String,
    pub last_commit: String,
}

/// One model as read from contributors.json.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ModelRow {
    pub company: String,
    pub model: String,
    pub version: String,
    pub commits: u64,
    pub lines_added: u64,
    pub lines_deleted: u64,
}

/// The credits read from a `contributors/` folder.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Credits {
    pub total_commits: u64,
    pub contributors: Vec<Person>,
    pub models: Vec<ModelRow>,
    /// One line per file that could not be read or parsed, with what that means for the window.
    pub warnings: Vec<String>,
}

/// Read `dir/contributors.json` and `dir/people.toml`. Never fails: problems end up in
/// [`Credits::warnings`].
pub fn load(dir: &Path) -> Credits {
    let mut warnings = Vec::new();
    let json = read(&dir.join("contributors.json"), "the About window shows no contributors", &mut warnings, |t| {
        serde_json::from_str::<Value>(t).map_err(|e| e.to_string())
    })
    .unwrap_or(Value::Null);
    let people = read(&dir.join("people.toml"), "contributors are shown by username only", &mut warnings, |t| {
        t.parse::<toml::Table>().map_err(|e| e.to_string())
    })
    .unwrap_or_default();
    let mut credits = from_parts(&json, &people);
    credits.warnings = warnings;
    credits
}

/// [`load`], written as Rust to `OUT_DIR/credits.rs`, with `cargo::rerun-if-changed` for both files
/// and a `cargo::warning` for each problem. Leaves an unchanged file alone, so its mtime doesn't make
/// cargo compile the crate again.
pub fn write_credits(dir: &Path) {
    for f in ["contributors.json", "people.toml"] {
        println!("cargo::rerun-if-changed={}", dir.join(f).display());
    }
    let credits = load(dir);
    for w in &credits.warnings {
        println!("cargo::warning={w}");
    }
    let Some(out_dir) = std::env::var_os("OUT_DIR") else {
        println!("cargo::warning=OUT_DIR is not set; the credits were not written");
        return;
    };
    let out = Path::new(&out_dir).join("credits.rs");
    let src = render(&credits);
    if std::fs::read_to_string(&out).is_ok_and(|old| old == src) {
        return;
    }
    if let Err(e) = std::fs::write(&out, src) {
        println!("cargo::warning=writing {}: {e}", out.display());
    }
}

fn read<T>(path: &Path, fallback: &str, warnings: &mut Vec<String>, parse: impl Fn(&str) -> Result<T, String>) -> Option<T> {
    let r = std::fs::read_to_string(path).map_err(|e| e.to_string()).and_then(|t| parse(&t));
    if let Err(e) = &r {
        warnings.push(format!("{}: {e}; {fallback}", path.display()));
    }
    r.ok()
}

fn s(v: &Value, k: &str) -> String {
    v.get(k).and_then(Value::as_str).unwrap_or("").to_string()
}

fn n(v: &Value, k: &str) -> u64 {
    v.get(k).and_then(Value::as_u64).unwrap_or(0)
}

fn rows<'a>(json: &'a Value, k: &str) -> &'a [Value] {
    json.get(k).and_then(Value::as_array).map_or(&[], Vec::as_slice)
}

/// A non-empty, trimmed name.
fn name(v: Option<&str>) -> Option<String> {
    v.map(str::trim).filter(|s| !s.is_empty()).map(str::to_string)
}

/// The credits from parsed files: `json` is contributors.json, `people` is people.toml.
pub fn from_parts(json: &Value, people: &toml::Table) -> Credits {
    let contributors = rows(json, "contributors")
        .iter()
        .filter_map(|c| {
            let login = c.get("login").and_then(Value::as_str).filter(|l| !l.is_empty())?;
            // Names only from a verified, self-chosen people.toml entry.
            let verified = c.get("people_entry").and_then(Value::as_bool) == Some(true);
            let entry = people.get("people").and_then(|p| p.get(login)).filter(|_| verified);
            let field = |k: &str| entry.and_then(|e| e.get(k)).and_then(toml::Value::as_str);
            let synced = entry.and_then(|e| e.get("sync_github_name")).and_then(toml::Value::as_bool) == Some(true);
            let display = name(field("display_name")).or_else(|| if synced { name(c.get("github_name").and_then(Value::as_str)) } else { None });
            Some(Person {
                login: login.to_string(),
                display_name: display,
                real_name: name(field("real_name")),
                prs: n(c, "prs"),
                commits: n(c, "commits"),
                lines_added: n(c, "lines_added"),
                lines_deleted: n(c, "lines_deleted"),
                binary_added: n(c, "binary_added"),
                binary_deleted: n(c, "binary_deleted"),
                first_commit: s(c, "first_commit"),
                last_commit: s(c, "last_commit"),
            })
        })
        .collect();
    let models = rows(json, "models")
        .iter()
        .map(|m| ModelRow {
            company: s(m, "company"),
            model: s(m, "model"),
            version: s(m, "version"),
            commits: n(m, "commits"),
            lines_added: n(m, "lines_added"),
            lines_deleted: n(m, "lines_deleted"),
        })
        .collect();
    Credits { total_commits: n(json, "commits"), contributors, models, warnings: Vec::new() }
}

fn opt(v: &Option<String>) -> String {
    match v {
        Some(x) => format!("Some({x:?})"),
        None => "None".into(),
    }
}

/// The credits as Rust: `TOTAL_COMMITS`, `CONTRIBUTORS` and `MODELS`.
pub fn render(c: &Credits) -> String {
    let mut o = String::new();
    let _ = writeln!(o, "// Generated by craft_credits::build from contributors/; do not edit.");
    let _ = writeln!(o, "pub static TOTAL_COMMITS: u64 = {};", c.total_commits);
    let _ = writeln!(o, "pub static CONTRIBUTORS: &[::craft_credits::Contributor] = &[");
    for p in &c.contributors {
        let _ = writeln!(
            o,
            "    ::craft_credits::Contributor {{ login: {:?}, display_name: {}, real_name: {}, prs: {}, commits: {}, lines_added: {}, lines_deleted: {}, binary_added: {}, binary_deleted: {}, first_commit: {:?}, last_commit: {:?} }},",
            p.login,
            opt(&p.display_name),
            opt(&p.real_name),
            p.prs,
            p.commits,
            p.lines_added,
            p.lines_deleted,
            p.binary_added,
            p.binary_deleted,
            p.first_commit,
            p.last_commit,
        );
    }
    let _ = writeln!(o, "];");
    let _ = writeln!(o, "pub static MODELS: &[::craft_credits::Model] = &[");
    for m in &c.models {
        let _ = writeln!(
            o,
            "    ::craft_credits::Model {{ company: {:?}, model: {:?}, version: {:?}, commits: {}, lines_added: {}, lines_deleted: {} }},",
            m.company, m.model, m.version, m.commits, m.lines_added, m.lines_deleted,
        );
    }
    let _ = writeln!(o, "];");
    o
}
